mapper.select:
select path, title, hit_count as hitCount
from sys_user_menu_hit
where user_id = #{userId} and tenant_id = #{tenantId}
order by hit_count desc, last_hit_time desc
limit #{limit}


select date_format(a.apply_bill_date, '%Y-%m-%d') as dayStr,
       coalesce(sum(e.qty), 0) as applyCount
from bas_apply a
inner join bas_apply_entry e on e.paren_id = a.id and e.tenant_id = #{scopedTenantId}
  and (e.del_flag is null or e.del_flag != 1)
where a.tenant_id = #{scopedTenantId}
  and (a.del_flag = 0 or a.del_flag is null)
  and a.apply_bill_status = 2
  and coalesce(a.bill_type, 1) = 1
  and a.apply_bill_date >= #{beginDate}
  and a.apply_bill_date <= #{endDate}
group by date_format(a.apply_bill_date, '%Y-%m-%d')


select date_format(dpa.purchase_bill_date, '%Y-%m-%d') as dayStr,
       coalesce(sum(e.qty), 0) as purchaseCount
from dep_purchase_apply dpa
inner join dep_purchase_apply_entry e on e.parent_id = dpa.id and e.tenant_id = #{scopedTenantId}
  and (e.del_flag is null or e.del_flag != 1)
where dpa.tenant_id = #{scopedTenantId}
  and (dpa.del_flag = 0 or dpa.del_flag is null)
  and dpa.purchase_bill_status = 2
  and dpa.purchase_bill_date >= #{beginDate}
  and dpa.purchase_bill_date <= #{endDate}
group by date_format(dpa.purchase_bill_date, '%Y-%m-%d')
